 jsonl_sha=hashlib.sha256(''.join(json.dumps(row,ensure_ascii=False)+'\n' for row in rows).encode()).hexdigest()
 assert s['results']['data'][name]['sha256']==jsonl_sha
 report['reconstructed_text_splits'][name]={'count':len(rows),'sha256':h,'sft_jsonl_sha256':jsonl_sha,'families':sorted({row['family'] for row in rows}),'effective_targets':sum(int((render_chat(row['messages'])[1]!=-100).sum()) for row in rows)}
for a,b in [('train','validation'),('train','test'),('validation','test')]: assert not ({x['family'] for x in text[a]}&{x['family'] for x in text[b]})
for name,rows in vision.items():
 assert r['data']['splits'][name]['records']==rows
 report['reconstructed_vision_splits'][name]={'count':len(rows),'sha256':records_sha256(rows),'effective_targets':sum(len(tok.encode(x['answer']))+1 for x in rows)}
for name in ['projector_only','partial','all','all_replay']:
 x=r['variants'][name];t=x['training'];ratio=x['replay_probability_per_example'];counts={'text_examples':0,'vision_examples':0,'text_targets':0,'vision_targets':0};history=[]
 assert t['steps']==160 and len(t['history'])==160
 for step in range(160):
  rng=random.Random(42+step);n=0
  for _ in range(4):
   if rng.random()<ratio:
    record=rng.choice(text['train']);count=int((render_chat(record['messages'])[1]!=-100).sum());category='text'
   else:
    record=rng.choice(vision['train']);count=len(tok.encode(record['answer']))+1;category='vision'
   counts[category+'_examples']+=1;counts[category+'_targets']+=count;n+=count
  history.append(n);assert n==t['history'][step]['effective_targets']
 total=counts['text_targets']+counts['vision_targets'];assert total==t['effective_tokens']==t['effective_targets']
 d={k:t[k] for k in ['steps','parameters','trainable_parameters','config','modal_config','effective_targets']};d.update(sampling_counts=counts,replay_probability=ratio,freeze_scope=x['freeze_scope'],learning_rate_from_fit_default=0.003,batch_examples_from_loss_default=4,history_target_sum=sum(history))
 for phase,records,flag,countkey in [('text_before',text['test'],'exact','matches'),('text_after',text['test'],'exact','matches'),('test',vision['test'],'exact_match','correct')]:
  samples=x[phase]['samples'];correct=0;expected_target_count=0;assert len(samples)==len(records)
