   expected=record['messages'][-1]['content'] if 'messages' in record else record['answer']
   assert sample.get('expected',sample.get('target'))==expected
   if 'messages' in record: assert sample['messages']==record['messages'][:-1]
   else: assert sample['family']==record['family'] and sample['question']==record['question']
   generated=sample['generated_ids'];raw=generated[:generated.index(tok.eos_id)] if tok.eos_id in generated else generated
   good=raw==tok.encode(expected);assert good==sample[flag];correct+=int(good);expected_target_count+=len(tok.encode(expected))+1
  assert correct==x[phase][countkey] and expected_target_count==x[phase]['effective_tokens']
  d[phase]={'correct_recount':correct,'denominator':len(samples),'effective_targets':expected_target_count,'eos_count':sum(q['eos'] for q in samples),'nll':x[phase].get('nll',x[phase].get('mean_token_nll'))}
 report['variants'][name]=d
for i,row in enumerate(text['test']):
